#include "KS/SRC/terrain.h"

void terrain::optimize()
{
  for (int i=regions.size(); --i>=0; )
  {
    regions[i]->optimize();
  }

  // Causes some bp_tree memory to be preallocated.  (dc 03/27/02)
  vector3d dummy;
    // PLEASE don't use nan!
  dummy.x=0.0f;
  dummy.y=0.0f;
  dummy.z=0.0f;
  tree->in_world(dummy, 0, dummy, dummy, dummy);
}
